#include "stdafx.h"#include "TCPR.h"KTCPR::KTCPR(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Register Used",  "Address",  "Data Type",  "Func. Code",  "Sel. Bit",};BOOL KTCPR::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( szText==" " )    return TRUE;  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    /*CStringA s;    if( 7==m_CurParameterID )      s.Format( "DisableValue = %s", szText.c_str() );*/    //if( !s.IsEmpty() )    m_settings.push_back( szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;  }  return FALSE;}